      "BZPC-0007-3A2C": ["手机银行后台", { act: "CHALLENGE", rid: "req-90247", note: "调用速率偏离基线，按档位动态挑战" }],
      "BZPC-0012-1D8E": ["核心网银门户", { act: "REJECT", rid: "req-90210", note: "调用速率偏离叠加重放防护命中，按档位拒绝访问" }],
